<?php
if(!defined('ABSPATH')){exit;}
final class Orion_AI_Diagnostics_Service{
 private Orion_Intent_Classifier $classifier;private Orion_Knowledge_Base $knowledge;private Orion_Semantic_Product_Planner $planner;
 public function __construct(Orion_Intent_Classifier $classifier,Orion_Knowledge_Base $knowledge,Orion_Semantic_Product_Planner $planner){$this->classifier=$classifier;$this->knowledge=$knowledge;$this->planner=$planner;}
 public function run(string $prompt,array $settings):array{$started=microtime(true);$classification=$this->classifier->classify($prompt,array(),array(),$settings);$report=array('prompt'=>$prompt,'provider'=>Orion_AI_Settings::provider($settings),'model'=>'google'===Orion_AI_Settings::provider($settings)?$settings['google_model']:$settings['openrouter_model'],'classification'=>$classification,'knowledge'=>array(),'products'=>array(),'outcome'=>'classified');$intent=$classification['intent']??'manager_follow_up';if('store_policy'===$intent){$query=$classification['policy_query']?:$prompt;$docs=$this->knowledge->relevant($query,5);$report['knowledge']=array('query'=>$query,'results'=>array_map(static fn($d)=>array('title'=>$d['title'],'source_url'=>$d['source_url'],'excerpt'=>mb_substr($d['markdown'],0,500)),$docs));$report['outcome']=$docs?'knowledge_candidates_found':'knowledge_no_results';}elseif(in_array($intent,array('project_recommendation','product_search'),true)){$kit=$this->planner->recommend($classification,$classification['state_patch']??array(),$settings);$report['products']=$kit;$report['outcome']=$kit['products']?'verified_products_found':'required_products_missing';}elseif('manager_follow_up'===$intent)$report['outcome']='classifier_requested_handoff';$report['duration_ms']=(int)round((microtime(true)-$started)*1000);return$report;}
}
